const SENTENCES = require("./src/flavourText");
const LOCATIONS = require("./src/location");
const GENERAL = require("./src/general");
const MOVES = require("./src/moves");

const sentences = (count) => {
  let sentences = "";
  for (let i = 0; i < count; i+= 1) {
    sentences += SENTENCES[Math.floor(Math.random()*SENTENCES.length)];
  }
  return sentences;
};

const paragraphs = (count) => {
  let paragraphs = "";
  for (let i = 0; i < count; i+= 1) {
    paragraphs += sentences(3) + "\n\n";
  }
  return paragraphs;
};

const place = () => {
  return LOCATIONS[Math.floor(Math.random()*LOCATIONS.length)];
};

const item = () => {
  return GENERAL[Math.floor(Math.random()*GENERAL.length)];
};

const move = () => {
  return MOVES[Math.floor(Math.random()*MOVES.length)];
};

exports.sentence = () => sentences(1);
exports.sentences = sentences;
exports.paragraph = () => sentences(3);
exports.paragraphs = paragraphs;
exports.place = place;
exports.item = item;
exports.ability = move;